namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
Fresh mozzarella
San Marzano tomatoes
Fresh basil
Olive oil
Salt", Steps = "1. Preheat oven to 475°F
2. Roll out dough
3. Spread crushed tomatoes
4. Add torn mozzarella
5. Bake 10-12 minutes
6. Top with fresh basil and olive oil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs
Yogurt
Garam masala
Tomato sauce
Heavy cream
Onion
Garlic
Ginger", Steps = "1. Marinate chicken in yogurt and spices
2. Grill or broil chicken
3. Sauté onion, garlic, ginger
4. Add tomato sauce and spices
5. Simmer with cream
6. Add chicken pieces", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco seasoning
Corn tortillas
Lettuce
Tomato
Cheddar cheese
Sour cream
Salsa", Steps = "1. Brown ground beef
2. Add taco seasoning and water
3. Simmer until thickened
4. Warm tortillas
5. Assemble with toppings", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles
Shrimp or tofu
Eggs
Bean sprouts
Green onions
Peanuts
Tamarind paste
Fish sauce
Sugar
Lime", Steps = "1. Soak rice noodles
2. Make pad thai sauce (tamarind, fish sauce, sugar)
3. Stir-fry protein
4. Push aside, scramble eggs
5. Add noodles and sauce
6. Toss with sprouts and peanuts
7. Serve with lime", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate
Butter
Eggs
Sugar
Flour
Vanilla extract", Steps = "1. Melt chocolate and butter
2. Whisk eggs and sugar
3. Combine mixtures
4. Fold in flour
5. Pour into greased ramekins
6. Bake at 425°F for 12 minutes
7. Invert and serve immediately", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 6, Title = "Caesar Salad", Category = "American", Ingredients = "Romaine lettuce
Parmesan cheese
Croutons
Caesar dressing
Lemon juice
Anchovy paste
Garlic", Steps = "1. Make dressing: whisk garlic, anchovy, lemon, olive oil
2. Tear romaine into pieces
3. Toss with dressing
4. Top with parmesan and croutons", AverageRating = 3.9, RatingCount = 6 },
        new Recipe { Id = 7, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Guanciale or pancetta
Eggs
Pecorino Romano
Black pepper", Steps = "1. Cook pasta al dente
2. Crisp guanciale in pan
3. Whisk eggs with pecorino and pepper
4. Toss hot pasta with guanciale
5. Remove from heat, add egg mixture
6. Toss quickly to create creamy sauce", AverageRating = 4.7, RatingCount = 18 },
        new Recipe { Id = 8, Title = "Mango Sticky Rice", Category = "Thai", Ingredients = "Glutinous rice
Coconut milk
Sugar
Salt
Ripe mango", Steps = "1. Soak sticky rice overnight
2. Steam rice until tender
3. Heat coconut milk with sugar and salt
4. Pour half over rice, let absorb
5. Slice mango
6. Serve rice with mango and remaining coconut sauce", AverageRating = 4.4, RatingCount = 10 },
    };

    private readonly Lock _lock = new();

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
        }
    }

    public List<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && stars is >= 1 and <= 5)
            {
                var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
                recipe.RatingCount++;
                recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
            }
        }
    }

    public void Submit(RecipeSubmission submission)
    {
        lock (_lock)
        {
            var newId = _recipes.Max(r => r.Id) + 1;
            _recipes.Add(new Recipe
            {
                Id = newId,
                Title = submission.Title,
                Category = submission.Category,
                Ingredients = submission.Ingredients,
                Steps = submission.Steps,
                AverageRating = 0,
                RatingCount = 0
            });
        }
    }
}

