@page "/recipes/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <strong>Success!</strong> Your recipe has been submitted. <a href="/">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label class="form-label">Recipe Title</label>
            <InputText class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect class="form-select" @bind-Value="submission.Category">
                <option value="">-- Select Category --</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients (one per line)</label>
            <InputTextArea class="form-control" rows="6" @bind-Value="submission.Ingredients" placeholder="2 cups flour&#10;1 cup sugar&#10;..." />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps (one per line)</label>
            <InputTextArea class="form-control" rows="6" @bind-Value="submission.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;..." />
        </div>

        <button type="submit" class="btn btn-success"
            disabled="@(string.IsNullOrWhiteSpace(submission.Title) || string.IsNullOrWhiteSpace(submission.Ingredients) || string.IsNullOrWhiteSpace(submission.Steps))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    private RecipeSubmission submission = new();
    private bool submitted;

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(submission.Title) &&
            !string.IsNullOrWhiteSpace(submission.Ingredients) &&
            !string.IsNullOrWhiteSpace(submission.Steps))
        {
            RecipeService.Submit(submission);
            submitted = true;
        }
    }
}

